INSERT INTO materials (category_id, name, description, unit, durability_rating, maintenance_level) VALUES
(1, 'Vitrified tile 600x600 glossy', 'Double-charged glossy vitrified tile with low water absorption; scratch and stain resistant, suited to busy living rooms, lobbies and showrooms.', 'sqft', 5, 'LOW'),
(1, 'Vitrified tile 800x1600 matt', 'Large-format matt vitrified slab that reduces grout lines; slip-resistant finish good for commercial corridors and high-traffic retail floors.', 'sqft', 5, 'LOW'),
(1, 'Ceramic floor tile 400x400', 'Budget ceramic floor tile for low-traffic rooms such as bedrooms and storerooms; easy to replace but chips under heavy loads.', 'sqft', 3, 'LOW'),
(1, 'Anti-skid ceramic tile', 'Textured anti-skid ceramic tile for bathrooms, balconies and wet kitchens; grips well when wet and cleans with a mop.', 'sqft', 4, 'LOW'),
(1, 'Italian marble Statuario', 'Premium white Italian marble with grey veining; luxurious look for hotel lobbies and villas, but needs sealing and periodic polishing and stains easily.', 'sqft', 4, 'HIGH'),
(1, 'Indian granite Black Galaxy', 'Hard-wearing black granite with gold flecks; extremely durable for staircases, entrances and heavy-footfall commercial floors.', 'sqft', 5, 'LOW'),
(1, 'Kota stone', 'Natural limestone from Rajasthan; very affordable and cool underfoot, common for verandas, schools and utility areas, needs occasional polishing.', 'sqft', 4, 'MEDIUM'),
(1, 'Engineered wood flooring oak', 'Real oak veneer over a stable plywood core; warm residential look for bedrooms and study rooms, sensitive to moisture and scratches.', 'sqft', 3, 'HIGH'),
(1, 'Luxury vinyl plank', 'Waterproof vinyl planks with a realistic wood look; quiet, affordable, quick click-lock installation for offices and rental apartments.', 'sqft', 3, 'LOW'),
(1, 'Epoxy floor coating', 'Seamless self-levelling epoxy coating for hospitals, labs, kitchens and warehouses; chemical resistant and hygienic with no joints to trap dirt.', 'sqft', 4, 'LOW'),
(2, 'Natural stone wall cladding', 'Split-face natural stone panels for feature walls and exterior facades; weather resistant and rugged, adds texture to elevations.', 'sqft', 5, 'LOW'),
(2, 'Exterior HPL cladding panel', 'High-pressure laminate panels for ventilated facades; UV stable colours, resists rain and fading, quick dry installation.', 'sqft', 5, 'LOW'),
(2, 'Wallpaper vinyl', 'Washable vinyl wallpaper in many patterns for bedrooms, hotel rooms and cafes; easy to change but can peel in humid rooms.', 'sqft', 2, 'MEDIUM'),
(2, 'Ceramic wall tile 300x600', 'Glazed ceramic wall tile for bathroom and kitchen walls; waterproof surface that wipes clean of oil and soap.', 'sqft', 4, 'LOW'),
(2, 'Fluted wooden wall panel', 'Decorative fluted MDF panel with wood veneer for reception walls and TV units; elegant look, keep away from water.', 'sqft', 3, 'MEDIUM'),
(2, 'Acoustic fabric wall panel', 'Fabric-wrapped mineral wool panel that absorbs sound in auditoriums, conference rooms and classrooms.', 'sqft', 3, 'MEDIUM'),
(2, 'Exposed brick tile', 'Thin clay brick tiles giving an exposed-brick look on interior walls of cafes and lofts without full masonry.', 'sqft', 4, 'LOW'),
(2, 'Gypsum wall plaster', 'Ready-mix gypsum plaster for smooth interior walls; faster than sand-cement plaster and crack resistant, interior use only.', 'bag', 4, 'LOW'),
(3, 'Gypsum board false ceiling', 'Plain gypsum board on a metal frame for seamless false ceilings with cove lighting in homes and offices.', 'sqft', 4, 'LOW'),
(3, 'Acoustic perforated gypsum board', 'Perforated gypsum ceiling board that reduces echo in large halls, classrooms and lobbies.', 'sqft', 4, 'LOW'),
(3, 'Mineral fibre ceiling tile 600x600', 'Lay-in grid ceiling tile for offices and hospitals; tiles lift out for easy access to wiring and ducts above.', 'sqft', 3, 'LOW'),
(3, 'PVC ceiling panel', 'Lightweight waterproof PVC panels for bathrooms, balconies and kitchens in humid or coastal homes.', 'sqft', 3, 'LOW'),
(3, 'Metal baffle ceiling', 'Aluminium linear baffles for airports, malls and open offices; modern industrial look, durable and fire safe.', 'sqft', 5, 'LOW'),
(3, 'Wooden slat ceiling', 'Solid wood or veneered slats for warm feature ceilings in lounges and restaurants; needs polish every few years.', 'sqft', 3, 'MEDIUM'),
(4, 'Interior emulsion premium', 'Washable low-sheen acrylic emulsion for interior walls; stain resistant and low odour, suited to homes and offices.', 'litre', 4, 'LOW'),
(4, 'Interior emulsion economy', 'Budget distemper-grade interior paint for rental units and back-of-house areas; not washable.', 'litre', 2, 'MEDIUM'),
(4, 'Anti-fungal exterior emulsion', 'Weatherproof exterior paint with anti-fungal and anti-algal additives for humid coastal climates and heavy monsoon areas.', 'litre', 4, 'LOW'),
(4, 'Textured exterior coating', 'Thick textured acrylic coating that hides wall imperfections and resists cracking on exterior facades.', 'litre', 5, 'LOW'),
(4, 'Waterproof terrace coating', 'Elastomeric waterproof coating for roofs and terraces; bridges hairline cracks and stops leaks during monsoon.', 'litre', 4, 'MEDIUM'),
(4, 'PU wood finish', 'Polyurethane clear finish for doors, panelling and furniture; glossy and scratch resistant.', 'litre', 4, 'MEDIUM'),
(4, 'Anti-microbial hospital paint', 'Interior paint with silver-ion anti-microbial protection for hospitals, clinics and schools; washable and hygienic.', 'litre', 4, 'LOW'),
(4, 'Enamel paint for metal', 'Oil-based enamel for railings, grills and gates; protects steel from rust with a glossy finish.', 'litre', 3, 'MEDIUM'),
(5, 'Quartz countertop', 'Engineered quartz slab for kitchen counters; non-porous, stain resistant and needs no sealing.', 'sqft', 5, 'LOW'),
(5, 'Granite countertop', 'Polished natural granite for kitchens and vanities; heat resistant and very durable, occasional sealing.', 'sqft', 5, 'LOW'),
(5, 'Solid surface Corian-type', 'Seamless acrylic solid surface for reception desks, hospital counters and vanities; repairable and hygienic.', 'sqft', 4, 'LOW'),
(5, 'Marble vanity top', 'Natural marble vanity top for premium bathrooms; elegant but etches with acidic cleaners.', 'sqft', 3, 'HIGH'),
(5, 'Stainless steel counter', 'Food-grade stainless steel counters for commercial kitchens and labs; hygienic and easy to sanitise.', 'sqft', 5, 'LOW'),
(5, 'Laminate countertop', 'Budget high-pressure laminate on plywood for pantries and office kitchenettes; avoid hot pans and standing water.', 'sqft', 2, 'MEDIUM'),
(6, 'uPVC sliding window', 'uPVC sliding windows with toughened glass; airtight, low maintenance, good sound and dust insulation for city homes.', 'sqft', 4, 'LOW'),
(6, 'Aluminium casement window', 'Powder-coated aluminium casement windows for offices and facades; slim profiles and strong frames.', 'sqft', 5, 'LOW'),
(6, 'Teak wood main door', 'Solid teak main door with traditional carving; very durable and secure, needs polishing every few years.', 'piece', 5, 'MEDIUM'),
(6, 'Flush door with laminate', 'Engineered flush door with decorative laminate for bedrooms and offices; affordable and termite treated.', 'piece', 3, 'LOW'),
(6, 'Fire-rated steel door', 'Two-hour fire-rated steel door for stairwells, electrical rooms and hotel corridors; meets fire code.', 'piece', 5, 'LOW'),
(6, 'Frameless glass partition', 'Toughened glass partition for cabins and meeting rooms; keeps offices open and bright.', 'sqft', 4, 'LOW'),
(6, 'WPC bathroom door', 'Wood-plastic composite door that is waterproof and termite proof; ideal for bathrooms and coastal homes.', 'piece', 4, 'LOW'),
(7, 'Wall-hung WC', 'Wall-mounted toilet with concealed cistern; easy to clean under, saves space in modern bathrooms.', 'piece', 4, 'LOW'),
(7, 'Floor-mounted WC', 'Standard floor-mounted toilet; budget friendly and simple to install for residential and school toilets.', 'piece', 4, 'LOW'),
(7, 'Countertop wash basin', 'Ceramic countertop basin for vanities in homes and hotels.', 'piece', 4, 'LOW'),
(7, 'Thermostatic shower mixer', 'Shower mixer that keeps water temperature steady; safer for children and the elderly.', 'piece', 4, 'LOW'),
(7, 'CPVC pipe 1 inch', 'CPVC hot and cold water pipe; corrosion free and long lasting for internal plumbing.', 'rft', 5, 'LOW'),
(7, 'Rainwater harvesting filter', 'Filter unit that cleans roof runoff before it enters a sump or recharge pit; required by many building bylaws.', 'piece', 4, 'MEDIUM'),
(7, 'Stainless steel kitchen sink', 'Double-bowl stainless steel sink with drainboard for home and pantry kitchens.', 'piece', 5, 'LOW'),
(8, 'AAC block', 'Lightweight autoclaved aerated concrete block for walls; good thermal insulation, faster construction and less load on structure.', 'piece', 4, 'LOW'),
(8, 'Red clay brick', 'Traditional burnt clay brick for load-bearing and partition walls; strong and widely available.', 'piece', 4, 'LOW'),
(8, 'Fly ash brick', 'Eco-friendly brick made from fly ash; uniform size, lower cost and reduced plaster consumption.', 'piece', 4, 'LOW'),
(8, 'OPC cement 53 grade', 'High-strength ordinary Portland cement for RCC slabs, columns and beams.', 'bag', 5, 'LOW'),
(8, 'PPC cement', 'Portland pozzolana cement for plastering and masonry; better workability and durability in humid conditions.', 'bag', 5, 'LOW'),
(8, 'TMT steel bar Fe 550D', 'Ductile thermo-mechanically treated steel reinforcement bar suited to earthquake-prone zones.', 'kg', 5, 'LOW'),
(8, 'Waterproofing admixture', 'Integral liquid admixture added to concrete and plaster to reduce water seepage in basements and bathrooms.', 'litre', 4, 'LOW'),
(8, 'Tile adhesive', 'Polymer-modified cement adhesive for fixing large tiles and stone; stronger and thinner than sand-cement bedding.', 'bag', 4, 'LOW');
