INSERT INTO projects (client_id, lead_architect_id, name, description, project_type, location, area_sqft, status, budget, start_date, end_date) VALUES
(1, 4, 'Roy Hotel Lobby Renovation', 'Renovation of a busy hotel lobby and reception needing premium, hard-wearing flooring, acoustic ceilings and an elegant feature wall.', 'HOSPITALITY', 'Mumbai', 7700, 'COMPLETED', 10850000, '2025-05-01', '2025-12-18'),
(2, 5, 'Sibal Villa', 'Two-storey family villa in a humid coastal climate; low-maintenance, moisture-resistant finishes and monsoon-proof exterior.', 'RESIDENTIAL', 'Pune', 10100, 'COMPLETED', 4600000, '2026-05-24', '2026-09-16'),
(3, 4, 'Bhagat School Classroom Block', 'New classroom wing with high-traffic corridors, easy-to-clean surfaces, good acoustics and child-safe toilets.', 'INSTITUTIONAL', 'Mysuru', 13900, 'IN_PROGRESS', 7800000, '2026-07-22', NULL),
(4, 4, 'Chaudhari Tech Park Office Floor', 'Open-plan office fit-out with glass cabins, modular ceiling for services access and durable carpet-free flooring.', 'COMMERCIAL', 'Mumbai', 8600, 'IN_PROGRESS', 6000000, '2026-01-15', NULL),
(5, 2, 'Bhat Apartment Interiors', 'Three-bedroom apartment interior with modern kitchen, wood-look bedrooms and premium bathrooms.', 'INTERIOR', 'Chennai', 3600, 'IN_PROGRESS', 8600000, '2025-11-11', NULL),
(6, 5, 'Rau Clinic Fit-out', 'Outpatient clinic requiring hygienic, seamless, chemical-resistant surfaces and anti-microbial finishes.', 'COMMERCIAL', 'Coimbatore', 15700, 'IN_PROGRESS', 10700000, '2025-12-16', NULL),
(7, 5, 'Nori Cafe and Restaurant', 'Rustic cafe with exposed-brick walls, warm wooden ceiling and a stainless steel commercial kitchen.', 'HOSPITALITY', 'Coimbatore', 12900, 'ON_HOLD', 10300000, '2025-12-17', NULL),
(8, 5, 'Chopra Row Houses', 'Cluster of affordable row houses built quickly with eco-friendly masonry and budget finishes.', 'RESIDENTIAL', 'Chennai', 9300, 'COMPLETED', 4300000, '2026-08-03', '2026-09-26'),
(9, 4, 'Kothari Retail Showroom', 'Ground-floor showroom with large-format tiles, bright facade cladding and frameless glass frontage.', 'COMMERCIAL', 'Pune', 15500, 'IN_PROGRESS', 7550000, '2025-08-08', NULL),
(10, 5, 'Handa Community Auditorium', 'Mid-size auditorium needing sound-absorbing walls and ceiling, fire-rated doors and durable aisles.', 'INSTITUTIONAL', 'Hyderabad', 9300, 'PLANNING', 6000000, '2025-09-16', NULL);
